.cu-card {
  display: block;
  border-radius: var(--cu-radius-lg);
  background: var(--cu-color-background-elevated, var(--cu-color-background-default));
  color: var(--cu-color-fg-default);
}

.cu-card--default,
.cu-card--outlined {
  box-shadow: none;
  border: var(--cu-border-width-hairline, 1px) solid var(--cu-color-border-default);
}

.cu-card--elevated {
  box-shadow: var(--cu-shadow-md, var(--cu-shadow-sm));
  border: var(--cu-border-width-hairline, 1px) solid
    color-mix(in srgb, var(--cu-color-fg-default) 8%, var(--cu-color-border-default));
}

.cu-card--padding-sm {
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
}

.cu-card--padding-md {
  padding-block: var(--cu-space-4, var(--cu-space-3));
  padding-inline: var(--cu-space-4, var(--cu-space-3));
}

.cu-card--padding-lg {
  padding-block: var(--cu-space-5, var(--cu-space-3));
  padding-inline: var(--cu-space-5, var(--cu-space-3));
}
